let analysisDays = toint({AnalysisPeriodDays});
let minHourlyActivity = toint({MinHourlyActivity});
let startTime = ago(totimespan(strcat(tostring(analysisDays), "d")));
let endTime = now();
// Get hourly process events per device
let processHourly = DeviceProcessEvents
    | where TimeGenerated >= startTime and TimeGenerated <= endTime
    | summarize ProcessCount = count() by DeviceId, bin(TimeGenerated, 1h);
// Get hourly other events per device
let otherHourly = union
    (DeviceNetworkEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime),
    (DeviceFileEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime),
    (DeviceRegistryEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime)
    | summarize OtherCount = count() by DeviceId, bin(TimeGenerated, 1h);
// Get device info for server detection
let deviceInfo = DeviceInfo
    | where TimeGenerated > ago(7d)
    | summarize arg_max(TimeGenerated, *) by DeviceId
    | project DeviceId, OSPlatform, DeviceType;
// Find "capped hours" - hours where device has other activity but no process events
let cappedHours = otherHourly
    | where OtherCount >= minHourlyActivity
    | join kind=leftanti processHourly on DeviceId, TimeGenerated
    | summarize CappedHours = count(), CappedDays = dcount(bin(TimeGenerated, 1d)) by DeviceId;
// Categorize devices
let highConfidence = cappedHours
    | where CappedDays >= 2 and CappedHours >= 4
    | count
    | extend Metric = "🔴 High Confidence Cap", Order = 1;
let mediumConfidence = cappedHours
    | where CappedDays == 1 and CappedHours >= 2
    | count
    | extend Metric = "🟠 Medium Confidence", Order = 2;
let lowConfidence = cappedHours
    | where CappedHours == 1
    | count
    | extend Metric = "🟡 Low Confidence", Order = 3;
// Count servers hitting cap
let serversCapped = cappedHours
    | join kind=inner deviceInfo on DeviceId
    | where OSPlatform contains "Server" or DeviceType == "Server"
    | count
    | extend Metric = "🖥️ High Confidence - Servers Capped", Order = 4;
let totalAnalysed = union
    (processHourly | summarize by DeviceId),
    (otherHourly | summarize by DeviceId)
    | summarize by DeviceId
    | count
    | extend Metric = "📱 Total Devices Analysed", Order = 5;
union highConfidence, mediumConfidence, lowConfidence, serversCapped, totalAnalysed
| order by Order asc
| project Metric, Count

