otherHourly
| where OtherCount >= minHourlyActivity
| join kind=leftanti processHourly on DeviceId, TimeGenerated
| extend HourOfDay = hourofday(TimeGenerated)
| summarize CapInstances = count(), UniqueDevices = dcount(DeviceId) by HourOfDay
| order by HourOfDay asc
| project 
    Hour = strcat(format_datetime(datetime(2000-01-01) + totimespan(strcat(tostring(HourOfDay), "h")), 'HH:mm')),
    CapInstances,
    UniqueDevices

