let endTime = now();
union
    (DeviceProcessEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime | extend EventType = "Process"),
    (DeviceNetworkEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime | extend EventType = "Network"),
