let analysisDays = toint({AnalysisPeriodDays});
let startTime = ago(totimespan(strcat(tostring(analysisDays), "d")));
let endTime = now();
let searchTerm = "{DeviceNameSearch}";
let matchingDevices = DeviceInfo
    | where TimeGenerated > ago(7d)
    | where isnotempty(searchTerm) and DeviceName contains searchTerm
    | summarize arg_max(TimeGenerated, *) by DeviceId
    | project DeviceId, DeviceName, OSPlatform, DeviceType
    | take 10;
matchingDevices
| project DeviceName, OSPlatform, DeviceType, DeviceId

let analysisDays = toint({AnalysisPeriodDays});
let startTime = ago(totimespan(strcat(tostring(analysisDays), "d")));
let endTime = now();
let searchTerm = "{DeviceNameSearch}";
let matchingDeviceIds = DeviceInfo
    | where TimeGenerated > ago(7d)
    | where isnotempty(searchTerm) and DeviceName contains searchTerm
    | summarize by DeviceId
    | take 1;
union
    (DeviceProcessEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime | where DeviceId in (matchingDeviceIds) | extend EventType = "Process"),
    (DeviceNetworkEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime | where DeviceId in (matchingDeviceIds) | extend EventType = "Network"),
    (DeviceFileEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime | where DeviceId in (matchingDeviceIds) | extend EventType = "File"),
    (DeviceRegistryEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime | where DeviceId in (matchingDeviceIds) | extend EventType = "Registry")
| summarize Count = count() by EventType, bin(TimeGenerated, 1h)
| order by TimeGenerated asc

let analysisDays = toint({AnalysisPeriodDays});
let minHourlyActivity = toint({MinHourlyActivity});
let startTime = ago(totimespan(strcat(tostring(analysisDays), "d")));
let endTime = now();
let searchTerm = "{DeviceNameSearch}";
let matchingDeviceIds = DeviceInfo
    | where TimeGenerated > ago(7d)
    | where isnotempty(searchTerm) and DeviceName contains searchTerm
    | summarize by DeviceId
    | take 1;
// Get hourly process events
let processHourly = DeviceProcessEvents
    | where TimeGenerated >= startTime and TimeGenerated <= endTime
    | where DeviceId in (matchingDeviceIds)
    | summarize ProcessCount = count() by bin(TimeGenerated, 1h);
// Get hourly other events
let otherHourly = union
    (DeviceNetworkEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime | where DeviceId in (matchingDeviceIds)),
    (DeviceFileEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime | where DeviceId in (matchingDeviceIds)),
    (DeviceRegistryEvents | where TimeGenerated >= startTime and TimeGenerated <= endTime | where DeviceId in (matchingDeviceIds))
    | summarize OtherCount = count() by bin(TimeGenerated, 1h);
// Show capped hours for this device
otherHourly
| where OtherCount >= minHourlyActivity
| join kind=leftouter processHourly on TimeGenerated
| extend ProcessCount = coalesce(ProcessCount, 0)
| where ProcessCount == 0
| project 
    CappedHour = format_datetime(TimeGenerated, 'yyyy-MM-dd HH:mm'),
    ProcessEvents = ProcessCount,
    OtherEvents = OtherCount,
    Status = "🔴 Process Dropped - Other Telemetry Continued"
| order by CappedHour desc
